import{G as e,W as t,n,rt as r}from"./chunks/framework.OKfwtFe7.js";var i=JSON.parse(`{"title":"金锤子（Golden Hammer）","description":"","frontmatter":{},"headers":[],"relativePath":"anti-patterns/golden-hammer.md","filePath":"anti-patterns/golden-hammer.md","lastUpdated":1791561689000}`),a={name:`anti-patterns/golden-hammer.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="金锤子-golden-hammer" tabindex="-1">金锤子（Golden Hammer） <a class="header-anchor" href="#金锤子-golden-hammer" aria-label="Permalink to “金锤子（Golden Hammer）”">​</a></h1><p>金锤子是&quot;手里的技术很顺手，于是所有问题都用它解&quot;。AntiPatterns 那本书把它列为最常见的技术类反模式之一 [S7]，特征是技术选型由熟悉度决定，而不是由问题决定。</p><h2 id="形态" tabindex="-1">形态 <a class="header-anchor" href="#形态" aria-label="Permalink to “形态”">​</a></h2><ol><li>团队的技术方案文档里，某项技术出现在每一栏，连明显不匹配的场景也在。</li><li>问&quot;为什么用它&quot;时，答案是&quot;我们熟&quot;或者&quot;以前这么做过&quot;，没有针对这个场景的对比。</li><li>需求里出现新约束（强一致、离线、嵌入式体积）时，先想怎么在现有技术上凑，再想换技术。</li><li>引入新技术要写三页论证，维持现有技术不用论证。</li></ol><p>任何团队都有偏好技术，正常的偏好和金锤子的界线在于：出现不匹配的信号时能不能重新评估。信号包括代码里出现大段绕过框架能力的手写逻辑、配置项数量超过业务代码行数、新人要先学一套自造的抽象才能改业务。</p><h2 id="代价" tabindex="-1">代价 <a class="header-anchor" href="#代价" aria-label="Permalink to “代价”">​</a></h2><ul><li>不匹配的场景里，抽象泄漏要长期补：框架管不到的地方得留逃生口，逃生口最后变成主路。</li><li>方案成本被低估：看起来&quot;复用现有能力&quot;，实际是把新问题改造成旧工具能处理的形状，改造工作没人算。</li><li>招聘与维护成本随时间上升：技术栈越窄，能接手的人越少。</li><li>依赖单点：这个工具的版本升级会牵动全部业务。</li></ul><h2 id="成因" tabindex="-1">成因 <a class="header-anchor" href="#成因" aria-label="Permalink to “成因”">​</a></h2><ol><li><strong>成功路径依赖</strong>：上个项目靠它成了，团队把&quot;上次的解法&quot;当成&quot;这类问题的解法&quot;。</li><li><strong>评估只做一次</strong>：选型时认真比过一次，之后新场景沿用，不再重跑评估。</li><li><strong>沉没成本</strong>：已经建了一堆库与工具，换技术意味着这些资产作废，于是继续加功能喂它。</li></ol><h2 id="走出来" tabindex="-1">走出来 <a class="header-anchor" href="#走出来" aria-label="Permalink to “走出来”">​</a></h2><ol><li><strong>先记账</strong>：把当前技术被硬套的场景列出来，每条写清&quot;为了用它多做了什么&quot;。不带这一步的换技术讨论会变成信仰之争。</li><li><strong>挑最小的一块切</strong>：选一个改动频率高、规模小的场景换掉，保留原技术在其他场景不动，用对比结果说话。</li><li><strong>留回滚口</strong>：新旧并存期把边界写进接口，别让两边互相 import。</li><li><strong>把评估写成门槛</strong>：之后新场景套用这套门槛，回答完&quot;约束是什么、这项技术哪条约束满足不了&quot;再决定沿用。</li></ol><p>换技术不是目标，让选型重新与约束挂钩才是。</p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to “示例”">​</a></h2><p>反面：为了不引入规则引擎，把折扣规则写成配置驱动的字符串表达式，再自己实现一个求值器。</p><div class="language-python line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">python</span><pre class="shiki github-dark" style="background-color:#24292e;color:#e1e4e8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#F97583;">class</span><span style="color:#B392F0;"> Pricing</span><span style="color:#E1E4E8;">:</span></span>
<span class="line"><span style="color:#F97583;">    def</span><span style="color:#79B8FF;"> __init__</span><span style="color:#E1E4E8;">(self, rules: list[</span><span style="color:#79B8FF;">str</span><span style="color:#E1E4E8;">]):</span></span>
<span class="line"><span style="color:#79B8FF;">        self</span><span style="color:#E1E4E8;">.rules </span><span style="color:#F97583;">=</span><span style="color:#E1E4E8;"> rules          </span><span style="color:#818e99;"># 规则是 &quot;qty&gt;10 and vip&quot; 这类字符串</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583;">    def</span><span style="color:#B392F0;"> discount</span><span style="color:#E1E4E8;">(self, order) -&gt; </span><span style="color:#79B8FF;">float</span><span style="color:#E1E4E8;">:</span></span>
<span class="line"><span style="color:#E1E4E8;">        total </span><span style="color:#F97583;">=</span><span style="color:#79B8FF;"> 0.0</span></span>
<span class="line"><span style="color:#F97583;">        for</span><span style="color:#E1E4E8;"> rule </span><span style="color:#F97583;">in</span><span style="color:#79B8FF;"> self</span><span style="color:#E1E4E8;">.rules:</span></span>
<span class="line"><span style="color:#F97583;">            if</span><span style="color:#79B8FF;"> self</span><span style="color:#E1E4E8;">._eval(rule, order):     </span><span style="color:#818e99;"># 自造求值器要处理优先级、转义、短路</span></span>
<span class="line"><span style="color:#E1E4E8;">                total </span><span style="color:#F97583;">+=</span><span style="color:#79B8FF;"> 5.0</span></span>
<span class="line"><span style="color:#F97583;">        return</span><span style="color:#E1E4E8;"> total</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583;">    def</span><span style="color:#B392F0;"> _eval</span><span style="color:#E1E4E8;">(self, expr, order) -&gt; </span><span style="color:#79B8FF;">bool</span><span style="color:#E1E4E8;">:</span></span>
<span class="line"><span style="color:#818e99;">        # 手写解析：优先级、括号、错误提示都要自己来，越写越像半个语言</span></span>
<span class="line"><span style="color:#79B8FF;">        ...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p>这里真正的问题是&quot;规则会频繁变、由业务方改&quot;。按问题选工具，要么用现成规则引擎，要么用代码表达规则、靠部署发版：</p><div class="language-python line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">python</span><pre class="shiki github-dark" style="background-color:#24292e;color:#e1e4e8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#F97583;">from</span><span style="color:#E1E4E8;"> dataclasses </span><span style="color:#F97583;">import</span><span style="color:#E1E4E8;"> dataclass</span></span>
<span class="line"><span style="color:#F97583;">from</span><span style="color:#E1E4E8;"> typing </span><span style="color:#F97583;">import</span><span style="color:#E1E4E8;"> Callable</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E1E4E8;">Rule </span><span style="color:#F97583;">=</span><span style="color:#E1E4E8;"> Callable[[</span><span style="color:#9ECBFF;">&quot;Order&quot;</span><span style="color:#E1E4E8;">], </span><span style="color:#79B8FF;">bool</span><span style="color:#E1E4E8;">]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583;">def</span><span style="color:#B392F0;"> qty_over</span><span style="color:#E1E4E8;">(n: </span><span style="color:#79B8FF;">int</span><span style="color:#E1E4E8;">) -&gt; Rule:</span></span>
<span class="line"><span style="color:#F97583;">    return</span><span style="color:#F97583;"> lambda</span><span style="color:#E1E4E8;"> o: o.qty </span><span style="color:#F97583;">&gt;</span><span style="color:#E1E4E8;"> n</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583;">def</span><span style="color:#B392F0;"> all_of</span><span style="color:#E1E4E8;">(</span><span style="color:#F97583;">*</span><span style="color:#E1E4E8;">rules: Rule) -&gt; Rule:</span></span>
<span class="line"><span style="color:#F97583;">    return</span><span style="color:#F97583;"> lambda</span><span style="color:#E1E4E8;"> o: </span><span style="color:#79B8FF;">all</span><span style="color:#E1E4E8;">(r(o) </span><span style="color:#F97583;">for</span><span style="color:#E1E4E8;"> r </span><span style="color:#F97583;">in</span><span style="color:#E1E4E8;"> rules)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#B392F0;">@dataclass</span></span>
<span class="line"><span style="color:#F97583;">class</span><span style="color:#B392F0;"> Pricing</span><span style="color:#E1E4E8;">:</span></span>
<span class="line"><span style="color:#E1E4E8;">    rules: list[Rule]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583;">    def</span><span style="color:#B392F0;"> discount</span><span style="color:#E1E4E8;">(self, order) -&gt; </span><span style="color:#79B8FF;">float</span><span style="color:#E1E4E8;">:</span></span>
<span class="line"><span style="color:#F97583;">        return</span><span style="color:#79B8FF;"> 5.0</span><span style="color:#F97583;"> if</span><span style="color:#E1E4E8;"> all_of(</span><span style="color:#F97583;">*</span><span style="color:#79B8FF;">self</span><span style="color:#E1E4E8;">.rules)(order) </span><span style="color:#F97583;">else</span><span style="color:#79B8FF;"> 0.0</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br></div></div><p>规则变成可测的函数，优先级、错误提示、解析都不用自己造。如果之后确实需要业务方在线编辑，再把规则来源换成现成引擎，改动只在 <code>Pricing</code> 的构造处。</p><h2 id="相关篇目" tabindex="-1">相关篇目 <a class="header-anchor" href="#相关篇目" aria-label="Permalink to “相关篇目”">​</a></h2><ul><li><a href="/hello-design-patterns/behavioral/strategy">策略模式</a>：把&quot;换算法&quot;做成换一个对象，是治金锤子的第一步。</li><li><a href="/hello-design-patterns/structural/adapter">适配器模式</a>：已经套上去、短期换不掉时，用适配器把不匹配的接口挡在边界内。</li><li><a href="/hello-design-patterns/structural/dependency-injection">依赖注入</a>：把具体技术藏在构造参数后面，换实现时只动装配处。</li></ul><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to “来源”">​</a></h2><ul><li>[S7] Brown 等，《AntiPatterns》，Wiley，1998。</li><li>[S17] SourceMaking 的 AntiPatterns 条目，形态与代价段落的结构参照。</li></ul>`,22)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};